mapper.select:
select count(*) from growth_mission_progress
where member_id = #{memberId} and mission_code = #{missionCode}
  and biz_type = 'registration' and biz_id = #{registrationId}
for update

select distinct mission_code from growth_mission_progress
where member_id = #{memberId} and biz_type = 'topic_completion_clawback' and biz_id = #{topicId}
for update

mapper.delete:
delete from growth_mission_progress
where member_id = #{memberId} and biz_type = 'topic_completion_clawback' and biz_id = #{topicId}
  and mission_code = #{missionCode}
